  .selectOption(lab.beneficiaryId);
await page.getByLabel('Importe (MXN)', { exact: true })
  .fill('100.00');

const sent = page.waitForResponse(r =>
  r.request().method() === 'POST' &&
  new URL(r.url()).pathname === '/api/transfers'
);
await page.getByRole('button',
  { name: 'Transferir', exact: true }).click();
const response = await sent;
expect(response.status()).toBe(201);

const account = await page.request.get(
  '/api/accounts/' + lab.sourceAccountId
);
expect(account.status()).toBe(200);
expect((await account.json()).balanceMinor).toBe(90000);

